<?php use CmuLms\View; $title='Question bank'; include __DIR__.'/../layout/header.php'; ?>
<section class="hero"><p><?=View::e($pool['course_code']??$pool['code'])?> · Question bank</p><h1><?=View::e($pool['title'])?></h1><p><?=View::e($pool['course_title'])?> · <?=View::e($total??count($questions))?> active questions</p></section>
<p><a href="?route=course&id=<?=View::e($pool['course_id'])?>" class="btn">Back to course</a></p>
<?php if(($user['role']??'')==='teacher' || ($user['role']??'')==='admin'): ?><section class="card"><h2>Question bank details</h2><form method="post" action="?route=pool-update" class="grid"><?=View::csrfField()?><input type="hidden" name="pool_id" value="<?=View::e($pool['id'])?>"><label>Bank title<input name="title" value="<?=View::e($pool['title'])?>" required></label><label>Term<select name="academic_period"><option value="midterm" <?=($pool['academic_period']??'')==='midterm'?'selected':''?>>Midterm</option><option value="final" <?=($pool['academic_period']??'')==='final'?'selected':''?>>Final</option></select></label><label>Topic<input name="topic" value="<?=View::e($pool['topic']??'')?>" placeholder="Topic"></label><label>Description<textarea name="description"><?=View::e($pool['description']??'')?></textarea></label><button>Save bank details</button></form></section><?php endif; ?>
<?php if(($user['role']??'')==='teacher' && !empty($courses)): ?><section class="card"><h2>Copy question bank</h2><p>Copy this complete bank and all of its questions to another course you teach.</p><form method="post" action="?route=pool-copy"><?=View::csrfField()?><input type="hidden" name="pool_id" value="<?=View::e($pool['id'])?>"><select name="target_course_id" required><option value="">Select destination course</option><?php foreach($courses as $course): if((int)$course['id']===(int)$pool['course_id']) continue; ?><option value="<?=View::e($course['id'])?>"><?=View::e($course['code'])?> · <?=View::e($course['title'])?></option><?php endforeach; ?></select><button>Copy entire question bank</button></form></section><?php endif; ?>
<?php foreach($questions as $i=>$q): $opts=json_decode($q['options'],true)?:[]; $answer=json_decode($q['answer'],true)[0]??''; ?>
<details class="card"><summary><strong>Question <?=$i+1?></strong> · <?=View::e($q['type'])?></summary><form method="post" action="?route=question-update"><?=View::csrfField()?><input type="hidden" name="question_id" value="<?=View::e($q['id'])?>"><input type="hidden" name="pool_id" value="<?=View::e($pool['id'])?>"><label>Question<textarea name="prompt" required><?=View::e($q['prompt'])?></textarea></label><?php foreach(['A','B','C','D'] as $k):?><label>Option <?=$k?><input name="option_<?=$k?>" value="<?=View::e(is_array($opts[$k]??null)?($opts[$k]['text']??''):$opts[$k]??'')?>"></label><?php endforeach;?><?php if($opts): ?><label>Correct answer<select name="answer"><?php foreach(array_keys($opts) as $k):?><option value="<?=View::e($k)?>" <?=$answer===$k?'selected':''?>><?=View::e($k)?></option><?php endforeach;?></select></label><?php else: ?><label>Correct answer<input name="answer" value="<?=View::e($answer)?>" required></label><?php endif; ?><button>Save question</button></form><?php if(!empty($target_pools)): ?><form method="post" action="?route=question-copy"><?=View::csrfField()?><input type="hidden" name="question_id" value="<?=View::e($q['id'])?>"><select name="target_pool_id" required><option value="">Copy this question to…</option><?php foreach($target_pools as $target): ?><option value="<?=View::e($target['id'])?>"><?=View::e($target['code'])?> · <?=View::e($target['title'])?></option><?php endforeach; ?></select><button>Copy question</button></form><?php endif; ?></details>
<?php endforeach; ?>
<section class="card"><label>Questions per page<select onchange="location.href='?route=pool-view&id=<?=View::e($pool['id'])?>&per_page='+this.value"><option value="10" <?=($per_page??10)===10?'selected':''?>>10</option><option value="20" <?=($per_page??10)===20?'selected':''?>>20</option><option value="50" <?=($per_page??10)===50?'selected':''?>>50</option></select></label><p><?php if(($page??1)>1): ?><a class="btn" href="?route=pool-view&id=<?=View::e($pool['id'])?>&page=<?=($page-1)?>&per_page=<?=($per_page??10)?>">Previous</a><?php endif; ?> Page <?=View::e($page??1)?> of <?=View::e($pages??1)?> <?php if(($page??1)<($pages??1)): ?><a class="btn" href="?route=pool-view&id=<?=View::e($pool['id'])?>&page=<?=($page+1)?>&per_page=<?=($per_page??10)?>">Next</a><?php endif; ?></p></section>
<?php include __DIR__.'/../layout/footer.php'; ?>
